/** Real Survival Duplifier settings/Undo never capture or restore private resource ownership. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativePortCopiedSettingsChecks {
    private static ServerLevel world;private static Actor actor;private static int ticks,checks;private static boolean running;
    private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer {Actor(ServerLevel level){super(level,new com.mojang.authlib.GameProfile(new UUID(0,2211493),"PortCopy"));}}
    private static boolean enabled(){return Boolean.getBoolean("vandorlabs.portCopyCheck");}
    private static void need(boolean ok,String why){checks++;if(!ok)throw new AssertionError("Native port Duplifier tick="+ticks+": "+why);}
    private static BlockPos source(NativePortKind kind){return new BlockPos(40,110,kind.ordinal()*8);}
    private static BlockPos target(NativePortKind kind){return source(kind).east(8);}
    private static NativeResourcePortEntity tile(BlockPos pos){need(world.getBlockEntity(pos) instanceof NativeResourcePortEntity,"installed port "+pos);return (NativeResourcePortEntity)world.getBlockEntity(pos);}
    private static void position(BlockPos pos){actor.setPos(pos.getX()+.5,pos.getY(),pos.getZ()-3);actor.setYRot(0);actor.setXRot(0);}
    private static boolean click(BlockPos pos){return actor.gameMode.useItemOn(actor,world,actor.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos).add(0,0,-.5),Direction.NORTH,pos,false)).consumesAction();}
    private static boolean use(BlockPos pos){position(pos);return click(pos);}
    private static void place(BlockPos pos,NativePortKind kind,boolean rotated){world.setBlock(pos.below(),Blocks.STONE.defaultBlockState(),3);position(pos);actor.setYRot(rotated?90:0);var stack=new ItemStack(NativePortBindings.BLOCKS.get(kind));actor.setItemInHand(InteractionHand.MAIN_HAND,stack);need(actor.gameMode.useItemOn(actor,world,stack,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos.below()).add(0,.5,0),Direction.UP,pos.below(),false)).consumesAction()&&stack.isEmpty(),"actual Survival port placement "+kind);}
    private static NativePortData.Configuration seed(){var faces=new ResourcePortSettings.Face[6];Arrays.fill(faces,ResourcePortSettings.Face.INPUT);return new NativePortData.Configuration(new ResourcePortSettings(faces,0,false,ResourcePortSettings.OnTexture.TRANSFERRING),0,ChannelList.EMPTY);}
    private static NativePortData.Configuration settings(boolean source){var faces=new ResourcePortSettings.Face[6];for(int i=0;i<6;i++)faces[i]=ResourcePortSettings.Face.values()[(i+(source?0:1))%3];return new NativePortData.Configuration(new ResourcePortSettings(faces,source?5_000_000_007L:3,source,source?ResourcePortSettings.OnTexture.REDSTONE:ResourcePortSettings.OnTexture.CONNECTED),source?2:1,source?ChannelList.of(7,23):ChannelList.of(5));}
    private static CompoundTag marker(boolean source){var tag=new CompoundTag();tag.putString("PortCopyOwner",source?"source":"target");tag.putInt("Batch",source?111:37);return tag;}
    private static FluidStack fluid(boolean source,int amount){var stack=new FluidStack(source?Fluids.WATER:Fluids.LAVA,amount);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(marker(source)));return stack;}
    private static ItemStack item(boolean source,int count){var stack=new ItemStack(source?Items.DIAMOND:Items.EMERALD,count);stack.set(DataComponents.CUSTOM_NAME,Component.literal(source?"Source cargo":"Target cargo"));stack.set(DataComponents.CUSTOM_DATA,CustomData.of(marker(source)));return stack;}
    private static void fill(NativeResourcePortEntity owner,boolean source){if(owner instanceof NativePowerPortEntity power)need(power.energy(Direction.NORTH).receiveEnergy(source?111:37,false)==(source?111:37),"real Power input");else if(owner instanceof NativeFluidPortEntity fluid)need(fluid.fluid(Direction.NORTH).fill(fluid(source,source?111:37),FluidAction.EXECUTE)==(source?111:37),"real distinct fluid/components input");else{var matter=(NativeMatterPortEntity)owner;need(matter.items(Direction.NORTH).insertItem(0,item(source,source?11:37),false).isEmpty(),"real distinct item/components input");if(!source){var extra=new ItemStack(Items.PAPER,3);extra.set(DataComponents.CUSTOM_DATA,CustomData.of(marker(false)));need(matter.items(Direction.NORTH).insertItem(8,extra,false).isEmpty(),"independent final inventory slot");}}}
    private static void addThree(NativeResourcePortEntity owner){if(owner instanceof NativePowerPortEntity power)need(power.energy(Direction.UP).receiveEnergy(3,false)==3,"live target energy changes after copy");else if(owner instanceof NativeFluidPortEntity fluid)need(fluid.fluid(Direction.UP).fill(fluid(false,3),FluidAction.EXECUTE)==3,"live target fluid changes after copy");else need(((NativeMatterPortEntity)owner).items(Direction.UP).insertItem(0,item(false,3),false).isEmpty(),"live target item changes after copy");}
    private static CompoundTag contents(NativeResourcePortEntity owner){var saved=owner.saveWithoutMetadata(world.registryAccess());var result=new CompoundTag();for(String key:List.of("PortEnergy","PortFluid","PortItems"))if(saved.contains(key))result.put(key,saved.get(key).copy());return result;}
    private static void clipboard(ItemStack tool,CompoundTag value){tool.set(DataComponents.CUSTOM_DATA,CustomData.of(value));}
    private static void exercise(NativePortKind kind){var from=tile(source(kind));var to=tile(target(kind));need(from.configure(seed())&&to.configure(seed()),"seed input configuration");fill(from,true);fill(to,false);need(from.configure(settings(true))&&to.configure(settings(false)),"distinct complete source/target configuration");from.getPersistentData().putByteArray("CopyPrivateOpaque",new byte[64]);to.getPersistentData().putByteArray("CopyPrivateOpaque",new byte[32]);var before=to.configuration();var originalState=to.getBlockState();var sourceContents=contents(from);var targetContents=contents(to);var tool=new ItemStack(NativeCopifierRegistrations.ITEM.get());actor.setItemInHand(InteractionHand.MAIN_HAND,tool);actor.setShiftKeyDown(true);need(use(source(kind)),"actual Duplifier shift capture "+kind);actor.setShiftKeyDown(false);var captured=NativeCopifierClipboard.settings(NativeCopifierItem.data(tool));need(captured!=null&&captured.getAllKeys().equals(Set.of("resource_port_settings")),"clipboard contains only appended typed settings");var expected=new CompoundTag();NativePortData.write(expected,from.configuration());need(captured.getCompound("resource_port_settings").equals(expected)&&!captured.toString().contains("CopyPrivateOpaque")&&!captured.toString().contains("PortEnergy")&&!captured.toString().contains("PortFluid")&&!captured.toString().contains("PortItems"),"all six faces/long rate/pull/art/mode/channels captured without resources");need(use(target(kind)),"normal real-item apply "+kind);need(to.configuration().equals(from.configuration())&&to.getBlockState()==originalState&&world.getBlockEntity(target(kind))==to,"complete settings copied without physical owner/state replacement");need(contents(from).equals(sourceContents)&&contents(to).equals(targetContents)&&to.getPersistentData().getByteArray("CopyPrivateOpaque").length==32,"copy leaves both private resource owners/components intact");addThree(to);var changedContents=contents(to);need(!changedContents.equals(targetContents),"target resources deliberately changed before Undo");need(NativeCopifierUndo.undo(actor),"existing real copied-settings Undo "+kind);need(to.configuration().equals(before)&&contents(to).equals(changedContents)&&contents(from).equals(sourceContents),"Undo restores settings and preserves later private resource changes");
        int option=-1;var catalog=DuplifierOptionCatalog.options();for(int i=0;i<catalog.length;i++)if(catalog[i].key.equals("resource_port_settings"))option=i;need(option>=64&&option<catalog.length,"appended port setting uses persisted multiword option");var root=NativeCopifierItem.data(tool);var words=NativeCopifierOptions.maskWords(root);need((words[option/64]&(1L<<(option%64)))!=0,"new tool enables appended setting by default");words[option/64]&=~(1L<<(option%64));clipboard(tool,NativeCopifierOptions.withMask(root,words));var unchanged=to.saveWithFullMetadata(world.registryAccess());need(!use(target(kind))&&unchanged.equals(to.saveWithFullMetadata(world.registryAccess())),"disabled appended mask is real-item no-op "+kind);words[option/64]|=1L<<(option%64);var enabled=NativeCopifierOptions.withMask(root,words);var malformed=enabled.copy();malformed.getCompound(NativeCopifierClipboard.SETTINGS).getCompound("resource_port_settings").putIntArray("PortFaces",new int[5]);clipboard(tool,malformed);need(!use(target(kind))&&unchanged.equals(to.saveWithFullMetadata(world.registryAccess())),"malformed clipboard refused before ownership/settings mutation");clipboard(tool,enabled);actor.setGameMode(GameType.SPECTATOR);need(!use(target(kind))&&unchanged.equals(to.saveWithFullMetadata(world.registryAccess())),"spectator actual-item apply refused");actor.setGameMode(GameType.SURVIVAL);position(target(kind).east(40));need(!click(target(kind))&&unchanged.equals(to.saveWithFullMetadata(world.registryAccess())),"out-of-reach actual-item apply refused");System.out.println("[vandorlabs][port-copy] case PASS "+kind+" settingsAll/longRate5000000007/resourceOwner37→40/Undo/maskOff/malformed/permissions");}
    @SubscribeEvent public static void started(ServerStartedEvent event){if(!enabled())return;try{world=event.getServer().overworld();actor=new Actor(world);actor.setGameMode(GameType.SURVIVAL);for(int x=2;x<=3;x++)for(int z=-1;z<=1;z++){world.setChunkForced(x,z,true);world.getChunk(x,z);}for(var kind:NativePortKind.values()){place(source(kind),kind,false);place(target(kind),kind,true);}running=true;}catch(Throwable failure){fail(failure);}}
    @SubscribeEvent public static void tick(ServerTickEvent.Post event){if(!running)return;try{need(++ticks<120,"bounded deferred port initialization");for(var kind:NativePortKind.values())if(tile(source(kind)).serverTicks<2||tile(target(kind)).serverTicks<2)return;for(var kind:NativePortKind.values())exercise(kind);running=false;System.out.println("[vandorlabs][port-copy] PASS checks="+checks+" threePorts/realSurvivalDuplifier/allSettings/noBufferCopy/Undo/maskOff/malformed/permissions");event.getServer().halt(false);}catch(Throwable failure){fail(failure);}}
    private static void fail(Throwable failure){running=false;failure.printStackTrace();System.out.println("[vandorlabs][port-copy] FAIL "+failure);if(world!=null)world.getServer().halt(false);}
}
